import{_ as a,o as i,c as n,a2 as o}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Conocimiento de hechizos y Core Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/magic/spell-knowledge.md","filePath":"es/game-design/magic/spell-knowledge.md"}'),r={name:"es/game-design/magic/spell-knowledge.md"};function t(s,e,d,c,l,u){return i(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="spell-knowledge-and-core-patterns" tabindex="-1">Conocimiento de hechizos y Core Patterns <a class="header-anchor" href="#spell-knowledge-and-core-patterns" aria-label="Enlace permanente a &quot;Conocimiento de hechizos y Core Patterns&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las decisiones enumeradas siguen Sin resolver. Los fundamentos existentes en estado Aceptado conservan su alcance. <strong>Implementación:</strong> no se ha establecido ninguna implementación de gameplay del Batch 04. <strong>Disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo conciliación documental, no validación en ejecución. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04 y al <a href="/Syrolands-Public/es/game-design/magic.html">diseño mágico anterior</a>.</p><p><a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Panorama de magia</a> · <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado y preguntas abiertas</a></p><h2 id="a-learned-structure-not-a-universal-spell-builder" tabindex="-1">Una estructura aprendida, no un constructor universal de hechizos <a class="header-anchor" href="#a-learned-structure-not-a-universal-spell-builder" aria-label="Enlace permanente a &quot;Una estructura aprendida, no un constructor universal de hechizos&quot;">​</a></h2><p>Un hechizo consta de un <strong>Core Pattern</strong> estable, modificadores aprendidos opcionales y ejecución. No es simplemente un botón fijo ni un entorno de construcción libre sin restricciones. Fireball, Ice Lance, Heal, Remove Curse y Teleport son identidades ilustrativas, no un catálogo aprobado.</p><p>Un Core Pattern puede definir familia/afinidad, forma de entrega, alcance base, modelo de selección de objetivo, Difficulty de ejecución, coste de maná/recursos, comportamiento de lesión/utilidad e interacciones pertinentes con armadura, extremidades o Concentration. Su identidad es suficientemente estable para aprenderla, enseñarla, inscribirla, conservarla, debatirla y construir variantes a su alrededor. Los metadatos exactos y definiciones de hechizos necesitan diseño posterior.</p><h2 id="knowledge-skill-and-practice-are-separate" tabindex="-1">Conocimiento, habilidad y práctica están separados <a class="header-anchor" href="#knowledge-skill-and-practice-are-separate" aria-label="Enlace permanente a &quot;Conocimiento, habilidad y práctica están separados&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capa</th><th>Significado Propuesto</th></tr></thead><tbody><tr><td>Conocimiento</td><td>Patrón o modificador aprendido permanentemente; obtenido de forma separada de la habilidad</td></tr><tr><td>Magery</td><td>Capacidad general de ejecución, control y consistencia; cumplir requisitos no garantiza fiabilidad</td></tr><tr><td>Familiarity</td><td>Práctica con un Core Pattern individual, fuera del límite de habilidades</td></tr><tr><td>Active Memory</td><td>Acceso preparado limitado; conocer un patrón no deja listas inmediatamente todas sus variantes</td></tr><tr><td>Mastery más amplia</td><td>Propuesta anterior de especialización por disciplina/afinidad; no es sinónimo de Familiarity por hechizo</td></tr></tbody></table><p><a href="/Syrolands-Public/es/game-design/magic.html#attempt-floor-versus-execution-difficulty">Umbral de intento frente a Difficulty</a> sigue siendo la referencia autoritativa de la propuesta: cumplir un umbral no otorga conocimiento ni éxito perfecto. <a href="/Syrolands-Public/es/game-design/magic.html#fizzle-versus-interruption">Fizzle frente a interrupción</a> mantiene separado el fallo estructural de ejecución de la perturbación bajo presión.</p><h2 id="discovery-has-provenance" tabindex="-1">El descubrimiento tiene procedencia <a class="header-anchor" href="#discovery-has-provenance" aria-label="Enlace permanente a &quot;El descubrimiento tiene procedencia&quot;">​</a></h2><p>Maestros, academias, escuelas, órdenes, grimorios, manuscritos, ruinas, culturas, lugares mágicos, criaturas, rituales, experimentación y enseñanza entre jugadores con límites apropiados pueden transmitir conocimiento. Geografía, historia y relaciones sociales deberían importar. Alcanzar 70 de Magery no debe desbloquear automáticamente un hechizo.</p><p>El <a href="/Syrolands-Public/es/game-design/magic.html#knowledge-and-world-institutions">modelo existente de instituciones, admisión y posición</a> conserva sus cuatro dimensiones independientes: disciplina, afinidad, técnica y tradición. El Core Pattern del Batch 04 aclara la identidad del hechizo; no fusiona estas dimensiones ni define definitivamente cada escuela. Conservar el conocimiento al perder el favor institucional sigue siendo la dirección propuesta anteriormente.</p><p>Aprender desde cero y las franjas ordinarias de habilidad pertenecen a <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">Habilidades y límite de habilidades</a>; <a href="/Syrolands-Public/es/game-design/characters/techniques-and-specialization.html">técnicas y escuelas</a> define el modelo de progresión compartido. <a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a> conserva y transmite estructuras solo dentro de reglas explícitas de enseñanza; un pergamino de lanzamiento comprable no equivale automáticamente a aprendizaje permanente.</p><h2 id="localized-effects-and-authority" tabindex="-1">Efectos localizados y autoridad <a class="header-anchor" href="#localized-effects-and-authority" aria-label="Enlace permanente a &quot;Efectos localizados y autoridad&quot;">​</a></h2><p>Cada patrón necesita un <a href="/Syrolands-Public/es/game-design/magic.html#localized-magic-and-injury">perfil de magia localizada</a> apropiado. Exposición de área, trauma local, quemaduras, deterioro por frío, fuerza contundente y perturbación de Concentration son candidatos. Anatomy puede apoyar el lanzamiento regional deliberado solo donde el patrón lo permita. No todos los hechizos pueden dirigirse a cualquier extremidad, y seleccionar una extremidad no garantiza el impacto.</p><p>El servidor es responsable del conocimiento aprendido, requisitos, recursos y resultados del lanzamiento. El cliente muestra el conocimiento permitido y envía intención. No se ha elegido esquema de hechizos, asignación de protocolo ni formato de guardado.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Catálogo final de patrones y taxonomía; prerrequisitos de aprendizaje; enseñanza y copia permitidas entre jugadores; restricciones de patrones prohibidos; información cualitativa de progreso; interacción entre Familiarity por patrón y Mastery más amplia; contratos anatómicos y de utilidad por hechizo. No se han fijado probabilidades de descubrimiento ni fórmula de ejecución.</p>',18)])])}const h=a(r,[["render",t]]);export{m as __pageData,h as default};
